// ***************
// Filename: py_sysctl_top.sv
// Author: FPGA Cores 4 U
// Description: py_sysctl with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map py_sysctl_regs
//   (u_regs, src/include/py_sysctl_regs.sv, ID "SCTL", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic py_sysctl (u_core,
//   src/py_sysctl.sv), joined by the register interface py_sysctl_regs_if
//   (u_regs_if). Generated by ip/scripts/regmap_gen.py from
//   py_sysctl_regs.json and the ports of py_sysctl: regenerate after changing
//   either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-20
module py_sysctl_top #(
  parameter int NCLK = 1,
  parameter logic [NCLK-1:0] CLK_EN_RST = '1,
  parameter bit CLKGEN = 1'b0
) (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  input  logic por_n,
  input  logic wdt_reset_i,
  input  logic boot_done_i,
  input  logic boot_err_i,
  input  logic [2:0] boot_err_code_i,
  output logic core_rst_n_o,
  output logic [NCLK-1:0] clk_en_o,
  input  logic clk_locked_i,
  output logic timer_irq_o
);
  // register interface between the register map and the logic
  py_sysctl_regs_if #(.NCLK(NCLK)) u_regs_if ();

  py_sysctl_regs #(
    .NCLK(NCLK),
    .CLK_EN_RST(32'(CLK_EN_RST))
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  py_sysctl #(
    .NCLK(NCLK),
    .CLK_EN_RST(CLK_EN_RST),
    .CLKGEN(CLKGEN)
  ) u_core (
    .aclk,
    .aresetn,
    .por_n,
    .wdt_reset_i,
    .boot_done_i,
    .boot_err_i,
    .boot_err_code_i,
    .core_rst_n_o,
    .clk_en_o,
    .clk_locked_i,
    .timer_irq_o,
    .regs(u_regs_if)
  );
endmodule
